package fixture

import (
	"context"
	"time"

	"go.temporal.io/sdk/activity"
	"go.temporal.io/sdk/client"
	"go.temporal.io/sdk/temporal"
	"go.temporal.io/sdk/worker"
	"go.temporal.io/sdk/workflow"
)

const (
	incidentTaskQueue = "ledger-incident"
	// PaymentsTaskQueue is the task queue of the ProcessLedgerEntry activities for the payments domain.
	PaymentsTaskQueue = "ledger-payments"
	coreTaskQueue     = "ledger-core"
	// RecoveryWorkerIdentity is the identity of the worker that NewRecoveryWorker returns.
	RecoveryWorkerIdentity = "recovery-worker"
)

var domain = temporal.NewSearchAttributeKeyKeyword("Domain")

// LedgerEntry is the input of ledgerEntryWorkflow.
type LedgerEntry struct {
	Domain   string `json:"domain"`
	Terminal bool   `json:"terminal"`
}

func ledgerEntryWorkflow(ctx workflow.Context, entry LedgerEntry) error {
	queue := coreTaskQueue
	if entry.Domain == "payments" {
		queue = PaymentsTaskQueue
	}
	return workflow.ExecuteActivity(workflow.WithActivityOptions(ctx, workflow.ActivityOptions{
		TaskQueue:           queue,
		StartToCloseTimeout: 10 * time.Second,
		RetryPolicy:         &temporal.RetryPolicy{InitialInterval: time.Second, BackoffCoefficient: 1, MaximumAttempts: 25},
	}), "ProcessLedgerEntry", entry).Get(ctx, nil)
}

func processLedgerEntry(ctx context.Context, entry LedgerEntry) error {
	if entry.Terminal {
		return temporal.NewNonRetryableApplicationError("LedgerWriteRejected: the ledger rejected the entry", "LedgerWriteRejected", nil)
	}
	if activity.GetInfo(ctx).Attempt == 1 {
		return temporal.NewApplicationError("LedgerServiceUnavailable: recovery still in progress", "LedgerServiceUnavailable")
	}
	return nil
}

// NewIncidentWorker returns an unstarted worker that runs ledgerEntryWorkflow on incidentTaskQueue, and no
// activities: while no recovery worker runs, the incident goes on and no ProcessLedgerEntry activity starts.
func NewIncidentWorker(c client.Client) worker.Worker {
	w := worker.New(c, incidentTaskQueue, worker.Options{LocalActivityWorkerOnly: true})
	w.RegisterWorkflow(ledgerEntryWorkflow)
	return w
}

// NewRecoveryWorker returns an unstarted worker, with identity RecoveryWorkerIdentity, that runs the
// ProcessLedgerEntry activities on PaymentsTaskQueue, which ends the incident for the payments domain. The first
// attempt of each fails with LedgerServiceUnavailable and the next succeeds; a terminal entry's fails with the
// non-retryable LedgerWriteRejected.
func NewRecoveryWorker(c client.Client) worker.Worker {
	w := worker.New(c, PaymentsTaskQueue, worker.Options{Identity: RecoveryWorkerIdentity, DisableWorkflowWorker: true})
	w.RegisterActivityWithOptions(processLedgerEntry, activity.RegisterOptions{Name: "ProcessLedgerEntry"})
	return w
}

// StartLedgerEntry starts ledgerEntryWorkflow for entry as workflow id, with search attribute Domain set to its
// domain.
func StartLedgerEntry(ctx context.Context, c client.Client, id string, entry LedgerEntry) (client.WorkflowRun, error) {
	return c.ExecuteWorkflow(ctx, client.StartWorkflowOptions{
		ID:                    id,
		TaskQueue:             incidentTaskQueue,
		TypedSearchAttributes: temporal.NewSearchAttributes(domain.ValueSet(entry.Domain)),
	}, ledgerEntryWorkflow, entry)
}

// Authorization: which tools each caller sees and may call, and on which targets it may
// use each one.

package server

import (
	"context"
	"errors"
	"fmt"
	"maps"
	"slices"
	"strings"

	"github.com/modelcontextprotocol/go-sdk/jsonrpc"
	"github.com/modelcontextprotocol/go-sdk/mcp"

	"github.com/temporalio/temporal-mcp/internal/config"
	"github.com/temporalio/temporal-mcp/internal/identity"
)

type targetsKey struct{}

// authorize leaves out of tools/list the tools the caller may use on no target,
// answers a call to one as the SDK answers a call to an unknown tool, and gives
// every other tool call the targets its caller may use the tool on, or, for
// list_available_targets, the targets its caller may use any tool on. Without
// auth, every caller may use every tool on every target.
func authorize(cfg *config.Config) mcp.Middleware {
	all := make([]string, len(cfg.Targets))
	for i, t := range cfg.Targets {
		all[i] = t.Name
	}
	return func(next mcp.MethodHandler) mcp.MethodHandler {
		return func(ctx context.Context, method string, req mcp.Request) (mcp.Result, error) {
			switch r := req.(type) {
			case *mcp.ListToolsRequest:
				res, err := next(ctx, method, req)
				if cfg.Auth == nil || err != nil {
					return res, err
				}
				list, ok := res.(*mcp.ListToolsResult)
				if !ok || list == nil {
					return nil, &jsonrpc.Error{Code: jsonrpc.CodeInternalError, Message: "internal error"}
				}
				g := grants(cfg.Authorization, req)
				list.Tools = slices.DeleteFunc(list.Tools, func(t *mcp.Tool) bool { return t == nil || len(g[t.Name]) == 0 })
				list.CacheScope = "private"
				return list, err
			case *mcp.CallToolRequest:
				targets := all
				if cfg.Auth != nil {
					g := grants(cfg.Authorization, req)
					if targets = g[r.Params.Name]; len(targets) == 0 {
						if rec := auditRecordFrom(ctx); rec != nil {
							rec.denied = true
						}
						return nil, &jsonrpc.Error{Code: jsonrpc.CodeInvalidParams, Message: fmt.Sprintf("unknown tool %q", r.Params.Name)}
					}
					if r.Params.Name == "list_available_targets" {
						targets = slices.Concat(slices.Collect(maps.Values(g))...)
					}
				}
				ctx = context.WithValue(ctx, targetsKey{}, targets)
			}
			return next(ctx, method, req)
		}
	}
}

// toolTargets returns the names of the targets the tool call in ctx may use.
func toolTargets(ctx context.Context) []string {
	targets, _ := ctx.Value(targetsKey{}).([]string)
	return targets
}

// mayUse reports whether the caller of req may use tool on the target with the given name.
func mayUse(cfg *config.Config, req mcp.Request, tool, target string) bool {
	return cfg.Auth == nil || slices.Contains(grants(cfg.Authorization, req)[tool], target)
}

// grants returns, for each tool, the targets the caller of req may use it on:
// those of every profile that gives it the tool through a rule its token matches.
func grants(a *config.Authorization, req mcp.Request) map[string][]string {
	g := map[string][]string{}
	extra := req.GetExtra()
	if extra == nil || extra.TokenInfo == nil {
		return g
	}
	caller := identity.CallerFromTokenInfo(extra.TokenInfo)
	for _, r := range a.Rules {
		if !matches(r, caller) {
			continue
		}
		p := a.Profiles[r.Profile]
		for _, tool := range p.Tools {
			g[tool] = append(g[tool], p.Targets...)
		}
	}
	return g
}

func matches(r config.Rule, caller *identity.Caller) bool {
	if r.Issuer != "" && r.Issuer != caller.Issuer {
		return false
	}
	switch v := caller.Claims[r.ClaimName].(type) {
	case string:
		if r.ClaimName == "scope" || r.ClaimName == "scp" {
			return slices.Contains(strings.Split(v, " "), r.ClaimValue)
		}
		return v == r.ClaimValue
	case []any:
		return slices.Contains(v, any(r.ClaimValue))
	}
	return false
}

func checkProfileTools(a *config.Authorization, tools []string) error {
	if a == nil {
		return nil
	}
	var errs []error
	for _, name := range slices.Sorted(maps.Keys(a.Profiles)) {
		for k, tool := range a.Profiles[name].Tools {
			if !slices.Contains(tools, tool) {
				errs = append(errs, fmt.Errorf("authorization: profiles: %q: tools[%d]: unknown tool %q; the tools are %s", name, k, tool, strings.Join(tools, ", ")))
			}
		}
	}
	return errors.Join(errs...)
}

// The search_workflows tool, which returns one page of the workflow runs that match a
// Visibility query, and the continuation that asks for the next page.

package server

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/base64"
	"errors"
	"fmt"
	"slices"
	"strconv"
	"strings"

	"github.com/google/jsonschema-go/jsonschema"
	"github.com/modelcontextprotocol/go-sdk/mcp"
	workflowpb "go.temporal.io/api/workflow/v1"
	"go.temporal.io/api/workflowservice/v1"
	"go.temporal.io/server/common/searchattribute/sadefs"
	"google.golang.org/grpc"

	"github.com/temporalio/temporal-mcp/internal/config"
	"github.com/temporalio/temporal-mcp/internal/temporal"
)

const maxContinuation = 4096

type searchWorkflowsInput struct {
	Target       string   `json:"target" jsonschema:"the name or an alias of a target"`
	Query        string   `json:"query,omitempty" jsonschema:"a Visibility query, such as WorkflowType = 'OrderWorkflow' AND ExecutionStatus = 'Running'; omit it for every run"`
	Fields       []string `json:"fields,omitempty" jsonschema:"the search attributes to return besides workflow_id and run_id, such as ExecutionStatus or CustomerId; ExecutionDuration is in nanoseconds; WorkflowType, ExecutionStatus, StartTime and CloseTime if omitted"`
	PageSize     int      `json:"page_size,omitempty" jsonschema:"the most runs to return"`
	Continuation string   `json:"continuation,omitempty" jsonschema:"the continuation from the next_call of the previous page"`
}

type workflowSearch struct {
	Workflows []map[string]any `json:"workflows"`
}

var defaultFields = []string{"WorkflowType", "ExecutionStatus", "StartTime", "CloseTime"}

// coreSearchAttributes reads workflow_id and run_id, which every row has, and the search attributes that Temporal
// keeps as fields of a run rather than in its search attribute map, in the form Visibility queries use. Visibility
// reports the Int ones only for a closed run.
var coreSearchAttributes = map[string]func(*workflowpb.WorkflowExecutionInfo) any{
	"workflow_id":     func(i *workflowpb.WorkflowExecutionInfo) any { return i.GetExecution().GetWorkflowId() },
	"run_id":          func(i *workflowpb.WorkflowExecutionInfo) any { return i.GetExecution().GetRunId() },
	"WorkflowId":      func(i *workflowpb.WorkflowExecutionInfo) any { return i.GetExecution().GetWorkflowId() },
	"RunId":           func(i *workflowpb.WorkflowExecutionInfo) any { return i.GetExecution().GetRunId() },
	"WorkflowType":    func(i *workflowpb.WorkflowExecutionInfo) any { return i.GetType().GetName() },
	"StartTime":       func(i *workflowpb.WorkflowExecutionInfo) any { return timeOf(i.GetStartTime()) },
	"ExecutionTime":   func(i *workflowpb.WorkflowExecutionInfo) any { return timeOf(i.GetExecutionTime()) },
	"CloseTime":       func(i *workflowpb.WorkflowExecutionInfo) any { return timeOf(i.GetCloseTime()) },
	"ExecutionStatus": func(i *workflowpb.WorkflowExecutionInfo) any { return i.GetStatus().String() },
	"TaskQueue":       func(i *workflowpb.WorkflowExecutionInfo) any { return i.GetTaskQueue() },
	"HistoryLength":   func(i *workflowpb.WorkflowExecutionInfo) any { return ifClosed(i, i.GetHistoryLength()) },
	"ExecutionDuration": func(i *workflowpb.WorkflowExecutionInfo) any {
		return ifClosed(i, int64(i.GetExecutionDuration().AsDuration()))
	},
	"StateTransitionCount": func(i *workflowpb.WorkflowExecutionInfo) any { return ifClosed(i, i.GetStateTransitionCount()) },
	"HistorySizeBytes":     func(i *workflowpb.WorkflowExecutionInfo) any { return ifClosed(i, i.GetHistorySizeBytes()) },
	"ParentWorkflowId":     func(i *workflowpb.WorkflowExecutionInfo) any { return ifSet(i.GetParentExecution().GetWorkflowId()) },
	"ParentRunId":          func(i *workflowpb.WorkflowExecutionInfo) any { return ifSet(i.GetParentExecution().GetRunId()) },
	"RootWorkflowId":       func(i *workflowpb.WorkflowExecutionInfo) any { return ifSet(i.GetRootExecution().GetWorkflowId()) },
	"RootRunId":            func(i *workflowpb.WorkflowExecutionInfo) any { return ifSet(i.GetRootExecution().GetRunId()) },
}

func ifClosed(i *workflowpb.WorkflowExecutionInfo, v int64) any {
	if i.GetCloseTime() == nil {
		return nil
	}
	return v
}

func ifSet(s string) any {
	if s == "" {
		return nil
	}
	return s
}

func searchWorkflowsInputSchema() *jsonschema.Schema {
	schema := schemaFor[searchWorkflowsInput]("search_workflows", "input", nil)
	boundPageSize(schema.Properties["page_size"])
	return schema
}

func searchWorkflows(cfg *config.Config, clients *temporal.Clients, names *searchAttributeNames) mcp.ToolHandlerFor[searchWorkflowsInput, envelope[workflowSearch]] {
	return func(ctx context.Context, req *mcp.CallToolRequest, in searchWorkflowsInput) (*mcp.CallToolResult, envelope[workflowSearch], error) {
		t, err := lookupTarget(ctx, cfg, in.Target)
		if err != nil {
			return nil, envelope[workflowSearch]{}, err
		}
		fields := in.Fields
		if fields == nil {
			fields = defaultFields
		}
		var pageToken []byte
		if in.Continuation != "" {
			if pageToken, err = decodeContinuation(in.Continuation, "search_workflows", t.Name, in.Query); err != nil {
				return nil, envelope[workflowSearch]{}, err
			}
		}
		if err := checkFields(ctx, req, cfg, clients, names, t, fields); err != nil {
			return nil, envelope[workflowSearch]{}, err
		}
		resp, err := callTemporal(ctx, t, func(ctx context.Context, opts ...grpc.CallOption) (*workflowservice.ListWorkflowExecutionsResponse, error) {
			return clients.Client(t.Name).WorkflowService().ListWorkflowExecutions(ctx, &workflowservice.ListWorkflowExecutionsRequest{
				Namespace:     t.Namespace,
				PageSize:      int32(in.PageSize),
				NextPageToken: pageToken,
				Query:         in.Query,
			}, opts...)
		})
		if err != nil {
			if in.Continuation != "" {
				return nil, envelope[workflowSearch]{}, continuationError(err, "search_workflows")
			}
			return nil, envelope[workflowSearch]{}, queryError(err)
		}
		out := envelope[workflowSearch]{Target: &t.Name, Result: workflowSearch{Workflows: []map[string]any{}}, Complete: len(resp.GetNextPageToken()) == 0}
		for _, info := range resp.GetExecutions() {
			row, err := workflowRow(info, fields)
			if err != nil {
				return nil, envelope[workflowSearch]{}, err
			}
			out.Result.Workflows = append(out.Result.Workflows, row)
		}
		if !out.Complete {
			continuation, ok := encodeContinuation(resp.GetNextPageToken(), "search_workflows", t.Name, in.Query)
			if !ok {
				// Temporal's page token is too long to hand out, so the page is returned without a next_call and stays incomplete.
				return nil, out, nil
			}
			args := map[string]any{"target": t.Name, "query": in.Query, "page_size": in.PageSize, "continuation": continuation}
			if in.Fields != nil {
				args["fields"] = in.Fields
			}
			out.NextCall = &nextCall{Name: "search_workflows", Arguments: args}
		}
		return nil, out, nil
	}
}

// checkFields returns an invalid_argument error naming, in the order given, each name in fields that is not
// workflow_id, run_id or a search attribute on t. Names in coreSearchAttributes, names already listed for t and, on a
// Temporal Cloud target with an API key, names with Temporal's reserved prefix (which may be built-ins newer than this
// server's sadefs) need no call; otherwise t's search attributes are listed once, and if the listing fails or is
// incomplete, every name passes unchecked.
func checkFields(ctx context.Context, req *mcp.CallToolRequest, cfg *config.Config, clients *temporal.Clients, names *searchAttributeNames, t *config.Target, fields []string) error {
	hasCloudOps := clients.CloudOps(t.Name) != nil
	passes := func(f string) bool {
		_, core := coreSearchAttributes[f]
		return core || names.has(t.Name, f) || hasCloudOps && strings.HasPrefix(f, sadefs.ReservedPrefix)
	}
	if !slices.ContainsFunc(fields, func(f string) bool { return !passes(f) }) {
		return nil
	}
	// fetchSearchAttributes stores t's names, so passes now checks fields against this listing.
	if _, _, complete, err := fetchSearchAttributes(ctx, clients, names, t); err != nil || !complete {
		return nil
	}
	var bad []string
	for _, f := range fields {
		if passes(f) {
			continue
		}
		bad = append(bad, strconv.Quote(f))
	}
	if len(bad) == 0 {
		return nil
	}
	msg := fmt.Sprintf("these fields are not search attributes on target %s: %s", t.Name, strings.Join(bad, ", "))
	if mayUse(cfg, req, "list_search_attributes", t.Name) {
		msg += "; call list_search_attributes for the target's search attributes"
	} else {
		msg += "; fix or remove them"
	}
	return &toolError{Code: "invalid_argument", Message: msg}
}

func workflowRow(info *workflowpb.WorkflowExecutionInfo, fields []string) (map[string]any, error) {
	row := map[string]any{}
	for _, name := range slices.Concat([]string{"workflow_id", "run_id"}, fields) {
		if value, ok := coreSearchAttributes[name]; ok {
			row[name] = value(info)
			continue
		}
		row[name] = nil
		if p, ok := info.GetSearchAttributes().GetIndexedFields()[name]; ok {
			v, err := searchAttribute(p)
			if err != nil {
				return nil, &toolError{Code: "temporal_unavailable", Message: fmt.Sprintf("the Temporal server returned search attribute %s in an unreadable form: %v", name, err)}
			}
			row[name] = v
		}
	}
	return row, nil
}

// queryError reports an invalid argument, which the Temporal server gives for a query it cannot run, as invalid_query.
func queryError(err error) error {
	if te := (*toolError)(nil); errors.As(err, &te) && te.Code == "invalid_argument" {
		te.Code = "invalid_query"
	}
	return err
}

// A continuation is the base64url of a version byte, the digest of the tool and the arguments it is bound to, and
// the position to resume from, such as Temporal's page token. It is unsigned: a changed position only resumes the
// same tool with the same arguments on the same namespace.
const continuationVersion = 1

func continuationDigest(tool string, binding []string) []byte {
	sum := sha256.Sum256([]byte(strings.Join(slices.Concat([]string{tool}, binding), "\x00")))
	return sum[:]
}

// encodeContinuation returns tool's continuation for position, and false if it is longer than decodeContinuation accepts.
func encodeContinuation(position []byte, tool string, binding ...string) (string, bool) {
	s := base64.RawURLEncoding.EncodeToString(slices.Concat([]byte{continuationVersion}, continuationDigest(tool, binding), position))
	return s, len(s) <= maxContinuation
}

func decodeContinuation(s, tool string, binding ...string) ([]byte, error) {
	if len(s) > maxContinuation {
		return nil, invalidContinuation(tool)
	}
	b, err := base64.RawURLEncoding.DecodeString(s)
	digest := continuationDigest(tool, binding)
	if err != nil || len(b) <= 1+len(digest) || b[0] != continuationVersion || !bytes.Equal(b[1:1+len(digest)], digest) {
		return nil, invalidContinuation(tool)
	}
	return b[1+len(digest):], nil
}

func invalidContinuation(tool string) *toolError {
	return &toolError{Code: "continuation_invalid", Message: fmt.Sprintf("continuation is not one that %s returned for these arguments; call %s again without it", tool, tool)}
}

// continuationError reports an invalid argument, which the Temporal server gives for a page token it cannot read, as
// tool's continuation_invalid.
func continuationError(err error, tool string) error {
	if te := (*toolError)(nil); errors.As(err, &te) && te.Code == "invalid_argument" {
		return invalidContinuation(tool)
	}
	return err
}

// The list_search_attributes tool, which lists the search attributes a target's Visibility
// queries can use. Temporal Cloud refuses OperatorService calls from customer credentials,
// so on Cloud the custom attributes come from the Cloud Ops API, which takes only API keys.

package server

import (
	"cmp"
	"context"
	"maps"
	"slices"
	"strings"
	"sync"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	enumspb "go.temporal.io/api/enums/v1"
	"go.temporal.io/api/operatorservice/v1"
	"go.temporal.io/cloud-sdk/api/cloudservice/v1"
	"go.temporal.io/server/common/searchattribute/sadefs"
	"google.golang.org/grpc"

	"github.com/temporalio/temporal-mcp/internal/config"
	"github.com/temporalio/temporal-mcp/internal/temporal"
)

type listSearchAttributesInput struct {
	Target string `json:"target" jsonschema:"the name or an alias of a target"`
}

type searchAttributeList struct {
	SearchAttributes []searchAttributeInfo `json:"search_attributes"`
}

type searchAttributeInfo struct {
	Name     string `json:"name"`
	Type     string `json:"type"`
	Category string `json:"category"`
}

// cloudSystemSearchAttributes are the system search attributes, which the Cloud Ops API does not list, from the Temporal server's own definitions.
var cloudSystemSearchAttributes = func() map[string]enumspb.IndexedValueType {
	attrs := sadefs.System()
	maps.Copy(attrs, sadefs.Predefined())
	return attrs
}()

// searchAttributeNames keeps the names of each target's search attributes from its last listing.
type searchAttributeNames struct {
	mu       sync.Mutex
	byTarget map[string]map[string]bool
}

func (n *searchAttributeNames) has(target, name string) bool {
	n.mu.Lock()
	defer n.mu.Unlock()
	return n.byTarget[target][name]
}

func (n *searchAttributeNames) store(target string, attrs ...map[string]enumspb.IndexedValueType) {
	names := map[string]bool{}
	for _, a := range attrs {
		for name := range a {
			names[name] = true
		}
	}
	n.mu.Lock()
	defer n.mu.Unlock()
	if n.byTarget == nil {
		n.byTarget = map[string]map[string]bool{}
	}
	n.byTarget[target] = names
}

func listSearchAttributes(cfg *config.Config, clients *temporal.Clients, names *searchAttributeNames) mcp.ToolHandlerFor[listSearchAttributesInput, envelope[searchAttributeList]] {
	return func(ctx context.Context, _ *mcp.CallToolRequest, in listSearchAttributesInput) (*mcp.CallToolResult, envelope[searchAttributeList], error) {
		t, err := lookupTarget(ctx, cfg, in.Target)
		if err != nil {
			return nil, envelope[searchAttributeList]{}, err
		}
		custom, system, complete, err := fetchSearchAttributes(ctx, clients, names, t)
		if err != nil {
			return nil, envelope[searchAttributeList]{}, err
		}
		list := searchAttributeList{SearchAttributes: []searchAttributeInfo{}}
		for category, attrs := range map[string]map[string]enumspb.IndexedValueType{"custom": custom, "system": system} {
			for name, typ := range attrs {
				list.SearchAttributes = append(list.SearchAttributes, searchAttributeInfo{Name: name, Type: typ.String(), Category: category})
			}
		}
		slices.SortFunc(list.SearchAttributes, func(a, b searchAttributeInfo) int {
			return cmp.Or(strings.Compare(a.Category, b.Category), strings.Compare(a.Name, b.Name))
		})
		return nil, envelope[searchAttributeList]{Target: &t.Name, Result: list, Complete: complete}, nil
	}
}

// fetchSearchAttributes returns t's custom and system search attributes and whether that is all of them, and stores
// their names in names only when it is.
func fetchSearchAttributes(ctx context.Context, clients *temporal.Clients, names *searchAttributeNames, t *config.Target) (custom, system map[string]enumspb.IndexedValueType, complete bool, err error) {
	switch ops := clients.CloudOps(t.Name); {
	case ops != nil:
		resp, err := callServer(ctx, t, cloudOpsAPI, func(ctx context.Context, opts ...grpc.CallOption) (*cloudservice.GetNamespaceResponse, error) {
			return ops.GetNamespace(ctx, &cloudservice.GetNamespaceRequest{Namespace: t.Namespace}, opts...)
		})
		if err != nil {
			return nil, nil, false, err
		}
		custom, system = map[string]enumspb.IndexedValueType{}, cloudSystemSearchAttributes
		for name, typ := range resp.GetNamespace().GetSpec().GetSearchAttributes() {
			// The Cloud Ops API's type names are the IndexedValueType names with another prefix.
			custom[name] = enumspb.IndexedValueType(enumspb.IndexedValueType_value["INDEXED_VALUE_TYPE_"+strings.TrimPrefix(typ.String(), "SEARCH_ATTRIBUTE_TYPE_")])
		}
	case temporal.IsCloud(t.Address):
		return map[string]enumspb.IndexedValueType{}, cloudSystemSearchAttributes, false, nil
	default:
		resp, err := callTemporal(ctx, t, func(ctx context.Context, opts ...grpc.CallOption) (*operatorservice.ListSearchAttributesResponse, error) {
			return clients.Client(t.Name).OperatorService().ListSearchAttributes(ctx, &operatorservice.ListSearchAttributesRequest{Namespace: t.Namespace}, opts...)
		})
		if err != nil {
			return nil, nil, false, err
		}
		custom, system = resp.GetCustomAttributes(), resp.GetSystemAttributes()
	}
	names.store(t.Name, custom, system)
	return custom, system, true, nil
}

