	missingKeyPath := filepath.Join(dir, "missing-api-key")
	missingKey := writeConfig(fmt.Sprintf("listen: 127.0.0.1:0\ntargets:\n  - {name: a, description: x, address: \"a:7233\", namespace: default, api_key: {file: %q}}\n", missingKeyPath))
